interface ReceiptLike {
  pickId: string;
  seq: number;
}

interface ProposalLike {
  level: string;
  where: string;
  check: string;
  mustFailOn: ReceiptLike[];
}

interface GroupLike {
  rank: number | null;
  key: string;
  kind: string;
  subject: string;
  level: string;
  stage: string | null;
  names: string[];
  picks: string[];
  pickCount: number;
  count: number;
  firstAt: string;
  lastAt: string;
  findings: FindingLike[];
  proposal: ProposalLike | null;
}

interface ReportLike {
  window: { since: string | null; until: string | null };
  picks: number;
  findings: number;
  lessons: GroupLike[];
  oneOffs: GroupLike[];
  skipped: { pickId: string; reason: string }[];
  summary: string;
}

interface PassLike {
  pass: number;
  labels?: Partial<Record<string, string>>;
}

