function weekLines(): { pickId: string; event: DraftEvent }[] {
  return WEEK_JSONL.split("\n").filter((line) => line.trim()).map((line) => JSON.parse(line) as { pickId: string; event: DraftEvent });
}

function weekLogs(): Log[] {
  const order: string[] = [];
  const byId = new Map<string, DraftEvent[]>();
  for (const row of weekLines()) {
    const list = byId.get(row.pickId);
    if (list) list.push(row.event);
    else {
      order.push(row.pickId);
      byId.set(row.pickId, [row.event]);
    }
  }
  return order.map((pickId) => ({ pickId, events: byId.get(pickId) ?? [] }));
}

function logById(logs: readonly Log[], pickId: string): Log {
  const found = logs.find((log) => log.pickId === pickId);
  assert.ok(found, pickId);
  return found;
}

function reportOf(logs: readonly Log[], window?: { since: string | null; until: string | null }): ReportLike {
  return (window ? gardener(logs, window) : gardener(logs)) as ReportLike;
}

function allFindings(report: ReportLike): FindingLike[] {
  return [...report.lessons, ...report.oneOffs].flatMap((group) => group.findings);
}

function group(report: ReportLike, key: string): GroupLike {
  const found = [...report.lessons, ...report.oneOffs].find((item) => item.key === key);
  assert.ok(found, key);
  return found;
}

function clone<T>(value: T): T {
  return structuredClone(value);
}

function lessonLog(pickId: string, topics: readonly (string | undefined)[], ts: string): Log {
  const events: DraftEvent[] = [
    {
      seq: 1,
      ts,
      type: "pick_created",
      by: "judge",
      key: "pick",
      payload: {
        id: pickId,
        idea: "crafted",
        source: "chat",
        target: "BoydVC/draft-day",
        n: 1,
        approval: "ask",
      },
    },
  ];
  topics.forEach((topic, index) => {
    const payload: Record<string, unknown> = { text: `note ${index}` };
    if (topic !== undefined) payload.topic = topic;
    events.push({
      seq: index + 2,
      ts,
      type: "lesson_recorded",
      by: "judge",
      key: `lesson:${index}`,
      payload,
    });
  });
  return { pickId, events };
}

function recast(log: Log, pickId: string): Log {
  const copy = clone(log);
  copy.pickId = pickId;
  for (const event of copy.events ?? []) {
    if (event.type === "pick_created") event.payload = { ...event.payload, id: pickId };
  }
  return copy;
}

function judgeTuples(report: ReportLike, pickId: string): Array<[string, number, number | null, string | null, string | null]> {
  return allFindings(report)
    .filter((finding) => finding.pickId === pickId && JUDGE_KINDS.has(finding.kind))
    .map((finding) => [finding.key, finding.seq, finding.pass, finding.label, finding.cand] as [string, number, number | null, string | null, string | null])
    .sort((a, b) => a[1] - b[1] || Number(a[2]) - Number(b[2]) || String(a[3]).localeCompare(String(b[3])) || a[0].localeCompare(b[0]));
}

function printed(text: string): string {
  return text.endsWith("\n") ? text.slice(0, -1) : text;
}

function hasControl(text: string): boolean {
  return /[\u0000-\u001F\u007F-\u009F]/.test(text);
}

async function dd(args: string[]): Promise<{ code: number; stdout: string; stderr: string }> {
  try {
    const { stdout, stderr } = await exec(process.execPath, ["--experimental-strip-types", "src/cli/dd.ts", ...args], {
      cwd: root,
      env: { ...process.env, NODE_NO_WARNINGS: "1" },
    });
    return { code: 0, stdout, stderr };
  } catch (error) {
    const err = error as { code?: number; stdout?: string; stderr?: string };
    return { code: err.code ?? 1, stdout: err.stdout ?? "", stderr: err.stderr ?? "" };
  }
}

async function splitWeek(dir: string, logs: readonly Log[] = weekLogs()): Promise<void> {
  for (const log of logs) {
    const pickDir = join(dir, "picks", log.pickId);
    await mkdir(pickDir, { recursive: true });
    const body = (log.events ?? []).map((event) => JSON.stringify(event)).join("\n") + "\n";
    await writeFile(join(pickDir, "events.jsonl"), body);
  }
}

function httpGet(url: string): Promise<{ status: number; body: string }> {
  return new Promise((resolve, reject) => {
    const req = request(url, (res) => {
      const chunks: Buffer[] = [];
      res.on("data", (chunk: Buffer) => chunks.push(chunk));
      res.on("end", () => resolve({ status: res.statusCode ?? 0, body: Buffer.concat(chunks).toString("utf8") }));
    });
    req.on("error", reject);
    req.end();
  });
}

function dayId(k: number, j: number): string {
  const date = new Date(Date.UTC(2026, 0, 1 + k));
  const y = date.getUTCFullYear();
  const m = String(date.getUTCMonth() + 1).padStart(2, "0");
  const d = String(date.getUTCDate()).padStart(2, "0");
  return `p-${y}${m}${d}-0${j}`;
}

async function uiFiles(): Promise<string[]> {
  const dir = join(root, "src/ui");
  const out: string[] = [];
  const entries = await readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.isFile()) out.push(join(dir, entry.name));
  }
  return out;
}

interface RecNode {
  tag: string;
  attrs: Record<string, string>;
  children: Array<RecNode | { text: string }>;
  addEventListener: () => void;
}

function renderLessons(source: string, report: unknown): RecNode[] {
  const sandbox = vm.createContext({ console }) as vm.Context & { draftDayLessons?: (report: unknown, el: (tag: string, attrs: unknown, children: unknown) => RecNode) => RecNode };
  vm.runInContext(source, sandbox, { filename: "src/ui/lessons.js" });
  assert.equal(typeof sandbox.draftDayLessons, "function");
  const made: RecNode[] = [];
  function el(tag: string, attrs: unknown, children: unknown): RecNode {
    const node: RecNode = {
      tag: String(tag).toLowerCase(),
      attrs: {},
      children: [],
      addEventListener() {},
    };
    if (attrs && typeof attrs === "object" && !Array.isArray(attrs)) {
      for (const [key, value] of Object.entries(attrs as Record<string, unknown>)) {
        if (value === undefined || value === null) continue;
        node.attrs[key] = String(value);
      }
    }
    const list = Array.isArray(children) ? children : children == null ? [] : [children];
    for (const child of list) {
      if (typeof child === "string" || typeof child === "number") node.children.push({ text: String(child) });
      else if (child && typeof child === "object") node.children.push(child as RecNode);
    }
    made.push(node);
    return node;
  }
  const rootNode = sandbox.draftDayLessons!(report, el);
  assert.equal(typeof rootNode, "object");
  assert.ok(rootNode);
  return made;
}

function textsOf(nodes: readonly RecNode[]): string[] {
  const texts: string[] = [];
  for (const node of nodes) {
    for (const child of node.children) {
      if ("text" in child) texts.push(child.text);
    }
  }
  return texts;
}

test("L1 sample lessons and one-offs", () => {
  assert.equal(createHash("sha256").update(WEEK_JSONL).digest("hex"), WEEK_SHA);
  assert.equal(EXPECTED_LINES.length, 36);
  assert.equal(stageLabel("physical"), "Physical");
  assert.equal(stageLabel("judging"), "Film Room");
  const report = reportOf(weekLogs());
  assert.equal(report.summary, "7 lessons from 5 picks · 27 findings · 6 one-offs");
  assert.equal(report.picks, 5);
  assert.equal(report.findings, 27);
  assert.deepEqual(report.skipped, []);
  assert.equal(report.lessons.length, 7);
  assert.equal(report.oneOffs.length, 6);
  LESSONS.forEach((expected, index) => {
    const lesson = report.lessons[index]!;
    assert.equal(lesson.rank, expected.rank, expected.key);
    assert.equal(lesson.key, expected.key);
    assert.equal(lesson.level, expected.level);
    assert.equal(lesson.stage, expected.stage);
    assert.deepEqual(lesson.picks, [...expected.picks]);
    assert.equal(lesson.pickCount, expected.picks.length);
    assert.equal(lesson.count, expected.count);
  });
  ONE_OFFS.forEach(([key, pickId, count], index) => {
    const item = report.oneOffs[index]!;
    assert.equal(item.key, key);
    assert.equal(item.rank, null);
    assert.equal(item.proposal, null);
    assert.deepEqual(item.picks, [pickId]);
    assert.equal(item.pickCount, 1);
    assert.equal(item.count, count);
  });
});

test("L2 sample proposals and receipts", () => {
  const report = reportOf(weekLogs());
  for (const expected of LESSONS) {
    const lesson = group(report, expected.key);
    assert.ok(lesson.proposal, expected.key);
    assert.equal(lesson.proposal.level, expected.level);
    assert.equal(lesson.proposal.where, expected.where);
    assert.equal(lesson.proposal.check, expected.check);
    assert.deepEqual(lesson.proposal.mustFailOn.map((receipt) => `${receipt.pickId}#${receipt.seq}`), [...expected.mustFailOn]);
  }
});

test("L3 finding extraction", () => {
  const report = reportOf(weekLogs());
  const journey = group(report, "gate:journey");
  assert.deepEqual(journey.findings.map((finding) => [finding.pickId, finding.seq, finding.pass, finding.label, finding.cand]), [
    ["p-20261011-01", 11, 1, "A", "c1"],
    ["p-20261012-01", 10, 1, "A", "c2"],
    ["p-20261012-01", 10, 1, "B", "c3"],
    ["p-20261012-01", 12, 2, "C", "c2"],
  ]);
  assert.deepEqual(journey.findings.map((finding) => finding.detail), ["", "", "", ""]);
  const tests = group(report, "score:tests");
  assert.deepEqual(tests.findings.map((finding) => finding.cand), ["c1", "c3", "c1", "c1"]);
  assert.deepEqual(tests.names, ["Tests prove behavior"]);
  const warroom = group(report, "score:warroom");
  assert.deepEqual(warroom.names, ["Board legibility", "Scorecard legibility"]);
  assert.equal(warroom.findings[1]?.cand, null);
  assert.equal(warroom.findings[1]?.label, "A");
  assert.deepEqual(group(report, "judge:unresolved-label").findings.map((finding) => finding.detail), ["label A", "label B", "label C"]);
  assert.equal(group(report, "judge:bad-criterion").findings[0]?.detail, "<script>alert(1)</script>");
  assert.equal(group(report, "lesson:xss").findings[0]?.detail, "<img src=x onerror=alert(1)>");
  const blocked = group(report, "not_verified:live-ui-verified").findings.find((finding) => finding.pickId === "p-20261014-01");
  assert.ok(blocked);
  assert.equal(blocked.detail.startsWith("<img src=x onerror=alert(1)>"), true);
  const inconclusive = group(report, "inconclusive:verifier-blocked");
  assert.equal(inconclusive.firstAt, "2026-10-12T16:45:00.000Z");
  assert.equal(inconclusive.lastAt, "2026-10-13T14:39:00.000Z");
  const verified = [
    "Legend and failed chip both visible at 390 px",
    "Run counts visible on all three cards",
    "Swap chip wraps at 390 px",
    "Gardener panel read at 390 px",
  ];
  for (const finding of allFindings(report)) {
    for (const evidence of verified) assert.equal(finding.detail.includes(evidence), false, finding.key);
  }
  const keys = [...report.lessons, ...report.oneOffs].map((item) => item.key).sort();
  assert.deepEqual(keys, [
    "gate:journey",
    "gate:tests",
    "inconclusive:verifier-blocked",
    "inconclusive:verifier-failed",
    "judge:bad-criterion",
    "judge:unresolved-label",
    "lesson:combine",
    "lesson:draft",
    "lesson:film room",
    "lesson:xss",
    "not_verified:live-ui-verified",
    "score:tests",
    "score:warroom",
  ]);
});

test("L4 label lookup matches the reducer", () => {
  const logs = weekLogs();
  const report = reportOf(logs);
  for (const log of logs) {
    assert.ok(log.events);
    const pick = reduce(log.events);
    if (pick?.judgement == null) continue;
    const passes = pick.judgement.passes as PassLike[];
    for (const finding of allFindings(report).filter((item) => item.pickId === log.pickId && JUDGE_KINDS.has(item.kind))) {
      const pass = passes.find((item) => item.pass === finding.pass);
      assert.ok(pass, `${log.pickId} ${finding.key} pass ${finding.pass}`);
      const expected = finding.label == null ? null : (pass.labels?.[finding.label] ?? null);
      assert.equal(finding.cand, expected, `${log.pickId} ${finding.key} ${finding.label}`);
    }
  }

  const unresolved = allFindings(report).filter((finding) => finding.pickId === "p-20261014-01" && JUDGE_KINDS.has(finding.kind));
  assert.equal(unresolved.every((finding) => finding.cand === null), true);
  assert.deepEqual(
    unresolved.filter((finding) => finding.key === "judge:unresolved-label").map((finding) => finding.detail),
    ["label A", "label B", "label C"],
  );

  const original = logById(logs, "p-20261012-01");
  assert.deepEqual(judgeTuples(reportOf([original]), original.pickId), P12_JUDGE);
  const stripped = clone(original);
  for (const event of stripped.events ?? []) {
    if (event.type === "judge_launched" || event.type === "judgement_recorded") delete event.payload.pass;
  }
  assert.deepEqual(judgeTuples(reportOf([stripped]), stripped.pickId), P12_JUDGE);

  const bare = clone(original);
  bare.events = (bare.events ?? []).filter((event) => event.type !== "judge_launched");
  const dropped = reportOf([bare]);
  assert.equal(dropped.summary, "0 lessons from 1 pick · 13 findings · 5 one-offs");
  assert.equal(group(dropped, "judge:unresolved-label").count, 6);
});

test("L5 repeats are counted in picks", () => {
  const alone = logById(weekLogs(), "p-20261014-01");
  assert.equal(reportOf([alone]).summary, "0 lessons from 1 pick · 8 findings · 5 one-offs");
  const paired = reportOf([alone, recast(alone, "p-20261014-02")]);
  assert.equal(paired.summary, "5 lessons from 2 picks · 16 findings · 0 one-offs");
  assert.equal(paired.oneOffs.length, 0);
  assert.deepEqual(paired.lessons.map((lesson) => [lesson.rank, lesson.key, lesson.pickCount, lesson.count]), [
    [1, "judge:unresolved-label", 2, 6],
    [2, "gate:tests", 2, 4],
    [3, "score:warroom", 2, 2],
    [4, "not_verified:live-ui-verified", 2, 2],
    [5, "lesson:film room", 2, 2],
  ]);
});

