test("L8 window", () => {
  const logs = weekLogs();
  const windowed = reportOf(logs, { since: "2026-10-12", until: "2026-10-14" });
  assert.equal(windowed.summary, "1 lesson from 2 picks · 9 findings · 4 one-offs");
  assert.deepEqual(windowed.window, { since: "2026-10-12", until: "2026-10-14" });
  assert.deepEqual(windowed.lessons.map((lesson) => lesson.key), ["inconclusive:verifier-blocked"]);
  assert.deepEqual(windowed.oneOffs.map((item) => [item.key, item.count]), [
    ["gate:journey", 3],
    ["score:tests", 2],
    ["lesson:draft", 1],
    ["lesson:film room", 1],
  ]);

  const wide = reportOf(logs, { since: "2026-10-11", until: "2026-10-16" });
  const open = reportOf(logs);
  assert.deepEqual(wide.window, { since: "2026-10-11", until: "2026-10-16" });
  assert.deepEqual(open.window, { since: null, until: null });
  const wideRest = { ...wide, window: open.window };
  assert.deepEqual(wideRest, open);

  const badTs = lessonLog("p-20261017-09", ["draft"], "not-a-date");
  badTs.events![0]!.ts = "not-a-date";
  const excluded = reportOf([...logs, badTs], { since: "2026-10-11", until: "2026-10-16" });
  assert.equal(excluded.picks, 5);
  assert.equal(excluded.findings, 27);
  assert.equal(allFindings(excluded).some((finding) => finding.pickId === "p-20261017-09"), false);
  const included = reportOf([...logs, badTs]);
  assert.equal(included.picks, 6);

  assert.deepEqual(lessonWindow(undefined, undefined), { ok: true, value: { since: null, until: null } });
  assert.deepEqual(lessonWindow(null, ""), { ok: true, value: { since: null, until: null } });
  assert.deepEqual(lessonWindow("", null), { ok: true, value: { since: null, until: null } });
  assert.deepEqual(lessonWindow("2026-10-12", ""), { ok: true, value: { since: "2026-10-12", until: null } });
  assert.deepEqual(lessonWindow("2024-02-29", "2024-03-01"), { ok: true, value: { since: "2024-02-29", until: "2024-03-01" } });
  assert.deepEqual(lessonWindow("2026-02-30", undefined), { ok: false, error: "since must be YYYY-MM-DD" });
  assert.deepEqual(lessonWindow("2026-02-29", null), { ok: false, error: "since must be YYYY-MM-DD" });
  assert.deepEqual(lessonWindow("2026-1-01", ""), { ok: false, error: "since must be YYYY-MM-DD" });
  assert.deepEqual(lessonWindow("yesterday", undefined), { ok: false, error: "since must be YYYY-MM-DD" });
  assert.deepEqual(lessonWindow("2026-10-11 ", null), { ok: false, error: "since must be YYYY-MM-DD" });
  assert.deepEqual(lessonWindow("2026-10-11T00:00:00Z", null), { ok: false, error: "since must be YYYY-MM-DD" });
  assert.deepEqual(lessonWindow(true, undefined), { ok: false, error: "since must be YYYY-MM-DD" });
  assert.deepEqual(lessonWindow(undefined, "2026-13-01"), { ok: false, error: "until must be YYYY-MM-DD" });
  assert.deepEqual(lessonWindow(null, true), { ok: false, error: "until must be YYYY-MM-DD" });
  assert.deepEqual(lessonWindow("2026-10-12", "2026-10-12"), { ok: false, error: "since must be before until" });
  assert.deepEqual(lessonWindow("2026-10-16", "2026-10-12"), { ok: false, error: "since must be before until" });
});

test("L9 skipped logs", async () => {
  const logs = weekLogs();
  const foreign = clone(logById(logs, "p-20261014-01").events ?? []);
  const mismatchedId = lessonLog("p-20261023-01", [], "2026-10-23T13:00:00.000Z");
  mismatchedId.events![0]!.payload = { ...mismatchedId.events![0]!.payload, id: "../etc/passwd" };
  const extras: Log[] = [
    { pickId: "../etc", events: [] },
    { pickId: "p-20261021-08", events: null },
    {
      pickId: "p-20261022-03",
      events: [{
        seq: 1,
        ts: "2026-10-22T13:00:00.000Z",
        type: "lesson_recorded",
        by: "judge",
        key: "lesson",
        payload: { topic: "draft", text: "no created" },
      }],
    },
    { pickId: "p-20261020-07", events: foreign },
    { pickId: "../../etc/passwd", events: null },
    { pickId: "p-20261011-01\u0000", events: [] },
    { pickId: "p-20261011-01/../p-20261012-01", events: [] },
    mismatchedId,
  ];
  for (const extra of extras) {
    if (extra.pickId === "p-20261021-08" || extra.pickId === "p-20261022-03" || extra.pickId === "p-20261020-07" || extra.pickId === "p-20261023-01") {
      assert.equal(isPickId(extra.pickId), true, extra.pickId);
    } else {
      assert.equal(isPickId(extra.pickId), false, extra.pickId);
    }
  }
  const report = reportOf([...logs, ...extras]);
  assert.equal(report.summary, "7 lessons from 5 picks · 27 findings · 6 one-offs");
  assert.equal(report.picks, 5);
  assert.equal(report.findings, 27);
  const expected = [
    { pickId: "../etc", reason: "bad pick id" },
    { pickId: "../../etc/passwd", reason: "bad pick id" },
    { pickId: "p-20261011-01\u0000", reason: "bad pick id" },
    { pickId: "p-20261011-01/../p-20261012-01", reason: "bad pick id" },
    { pickId: "p-20261020-07", reason: "id mismatch" },
    { pickId: "p-20261021-08", reason: "unreadable" },
    { pickId: "p-20261022-03", reason: "no pick_created" },
    { pickId: "p-20261023-01", reason: "id mismatch" },
  ].sort((a, b) => (a.pickId < b.pickId ? -1 : a.pickId > b.pickId ? 1 : 0));
  assert.deepEqual(report.skipped.map((item) => ({ pickId: item.pickId, reason: item.reason })), expected);

  const dir = await mkdtemp(join(tmpdir(), "dd-lessons-bad-"));
  await splitWeek(dir);
  await appendFile(join(dir, "picks", "p-20261015-01", "events.jsonl"), "{not json\n");
  const result = await dd(["lessons", "--data", dir]);
  assert.equal(result.code, 0, result.stderr);
  assert.equal(printed(result.stdout).split("\n").includes("skipped p-20261015-01: unreadable"), true, result.stdout);
  assert.equal(printed(result.stdout).includes("7 lessons from 4 picks · 23 findings · 2 one-offs"), true, result.stdout);
});

test("L10 order-independent", () => {
  const logs = weekLogs();
  const base = reportOf(logs);
  function shuffle<T>(items: readonly T[], seed: number): T[] {
    const out = items.slice();
    let state = seed;
    for (let i = out.length - 1; i > 0; i -= 1) {
      state = (state * 1664525 + 1013904223) >>> 0;
      const j = state % (i + 1);
      const swap = out[i]!;
      out[i] = out[j]!;
      out[j] = swap;
    }
    return out;
  }
  for (const seed of [3, 11, 29]) {
    const shuffled = shuffle(logs, seed).map((log) => ({
      pickId: log.pickId,
      events: log.events ? shuffle(log.events, seed + 1) : null,
    }));
    assert.deepEqual(reportOf(shuffled), base);
  }
});

test("L11 dd lessons", async () => {
  const dir = await mkdtemp(join(tmpdir(), "dd-lessons-week-"));
  await splitWeek(dir);
  const text = await dd(["lessons", "--data", dir]);
  assert.equal(text.code, 0, text.stderr);
  assert.equal(printed(text.stdout), EXPECTED_LINES.join("\n"));
  const json = await dd(["lessons", "--data", dir, "--json"]);
  assert.equal(json.code, 0, json.stderr);
  assert.equal(hasControl(printed(json.stdout)), false);
  assert.deepEqual(JSON.parse(json.stdout), reportOf(weekLogs()));
  assert.equal(printed(lessonsText(reportOf(weekLogs()) as unknown as LessonsReport)), EXPECTED_LINES.join("\n"));

  const badSince = await dd(["lessons", "--data", dir, "--since", "2026-02-30"]);
  assert.equal(badSince.code, 2);
  assert.match(badSince.stderr, /^error: since must be YYYY-MM-DD\n?$/);
  const badUntil = await dd(["lessons", "--data", dir, "--until", "yesterday"]);
  assert.equal(badUntil.code, 2);
  assert.match(badUntil.stderr, /^error: until must be YYYY-MM-DD\n?$/);
  const order = await dd(["lessons", "--data", dir, "--since", "2026-10-16", "--until", "2026-10-12"]);
  assert.equal(order.code, 2);
  assert.match(order.stderr, /^error: since must be before until\n?$/);
  const bare = await dd(["lessons", "--data", dir, "--since"]);
  assert.equal(bare.code, 2, bare.stdout + bare.stderr);
  assert.match(bare.stderr, /^error: since must be YYYY-MM-DD\n?$/);
  const bareUntil = await dd(["lessons", "--data", dir, "--until"]);
  assert.equal(bareUntil.code, 2);
  assert.match(bareUntil.stderr, /^error: until must be YYYY-MM-DD\n?$/);

  const help = await dd(["help"]);
  assert.equal(help.code, 0);
  assert.match(help.stdout, /dd lessons \[--since YYYY-MM-DD\] \[--until YYYY-MM-DD\]/);
});

test("L12 lessons API", async () => {
  const dir = await mkdtemp(join(tmpdir(), "dd-lessons-api-"));
  await splitWeek(dir);
  const server = await startServer({
    host: "127.0.0.1",
    port: 0,
    dataDir: dir,
    configPath: join(root, "draftday.config.json"),
    targetsPath: join(root, "targets.json"),
  });
  try {
    const open = await httpGet(`${server.url}/api/lessons`);
    assert.equal(open.status, 200);
    const cli = await dd(["lessons", "--data", dir, "--json"]);
    assert.deepEqual(JSON.parse(open.body), JSON.parse(cli.stdout));
    const windowed = await httpGet(`${server.url}/api/lessons?since=2026-10-12&until=2026-10-14`);
    assert.equal(windowed.status, 200);
    const cliWindow = await dd(["lessons", "--data", dir, "--json", "--since", "2026-10-12", "--until", "2026-10-14"]);
    assert.deepEqual(JSON.parse(windowed.body), JSON.parse(cliWindow.stdout));
    const ignored = await httpGet(`${server.url}/api/lessons?since=2026-10-12&until=2026-10-14&pick=../etc`);
    assert.deepEqual(JSON.parse(ignored.body), JSON.parse(windowed.body));
    const bad = await httpGet(`${server.url}/api/lessons?since=2026-10-16&until=2026-10-12`);
    assert.equal(bad.status, 400);
    assert.deepEqual(JSON.parse(bad.body), { error: "since must be before until" });
    const js = await httpGet(`${server.url}/lessons.js`);
    const css = await httpGet(`${server.url}/lessons.css`);
    assert.equal(js.status, 200);
    assert.equal(css.status, 200);
    assert.match(js.body, /draftDayLessons/);
    assert.ok(css.body.length > 0);
  } finally {
    await server.close();
  }
});

