test("L14 terminal-safe text", async () => {
  const logs = [
    lessonLog("p-20261201-01", ["\u001b[2Jwipe"], "2026-12-01T13:00:00.000Z"),
    lessonLog("p-20261201-02", ["\u001b[2jWIPE\u0007"], "2026-12-01T13:00:00.000Z"),
  ];
  const text = lessonsText(reportOf(logs) as unknown as LessonsReport);
  assert.equal(printed(text), [
    "0 lessons from 2 picks · 2 findings · 2 one-offs",
    "one-offs",
    "- lesson:?[2jwipe  p-20261201-01  1 finding",
    "- lesson:?[2jwipe?  p-20261201-02  1 finding",
  ].join("\n"));
  for (const line of printed(text).split("\n")) assert.equal(hasControl(line), false, JSON.stringify(line));

  const hostile = [
    lessonLog("p-20261202-01", ["\u0000bell\u007f\u009f\nring"], "2026-12-02T13:00:00.000Z"),
    lessonLog("p-20261202-02", ["\u0000BELL\u007f\u009f\nRING"], "2026-12-02T13:00:00.000Z"),
  ];
  const hostileText = printed(lessonsText(reportOf(hostile) as unknown as LessonsReport));
  for (const line of hostileText.split("\n")) assert.equal(hasControl(line), false, JSON.stringify(line));
  assert.match(hostileText, /Boyd names the engine check for "\?bell\?\? ring"/);
  assert.match(hostileText, /lesson:\?bell\?\? ring/);

  const dir = await mkdtemp(join(tmpdir(), "dd-lessons-ctrl-"));
  await splitWeek(dir, logs);
  const json = await dd(["lessons", "--data", dir, "--json"]);
  assert.equal(json.code, 0, json.stderr);
  const body = printed(json.stdout);
  assert.equal(hasControl(body), false);
  assert.match(body, /\\u001b/);
  assert.match(body, /\\u0007/);
  const parsed = JSON.parse(body) as ReportLike;
  const keys = [...parsed.lessons, ...parsed.oneOffs].map((item) => item.key);
  assert.equal(keys.includes("lesson:\u001b[2jwipe"), true);
  assert.equal(keys.includes("lesson:\u001b[2jwipe\u0007"), true);
});

test("L18 no markup from payloads", async () => {
  const source = await readFile(join(root, "src/ui/lessons.js"), "utf8");
  const banned = ["innerHTML", "outerHTML", "insertAdjacentHTML", "document.write", "eval(", "new Function"];
  for (const file of await uiFiles()) {
    const text = await readFile(file, "utf8");
    for (const token of banned) assert.equal(text.includes(token), false, `${file} contains ${token}`);
  }

  function assertSafe(nodes: RecNode[], label: string): void {
    for (const node of nodes) {
      assert.equal(["img", "script", "iframe"].includes(node.tag), false, `${label} <${node.tag}>`);
      for (const key of Object.keys(node.attrs)) assert.equal(/^on/i.test(key), false, `${label} ${key}`);
      if ("href" in node.attrs) assert.match(node.attrs.href, /^#\/picks\/p-\d{8}-\d{2}$/, `${label} ${node.attrs.href}`);
    }
  }

  const sample = renderLessons(source, reportOf(weekLogs()));
  assertSafe(sample, "sample");
  const sampleText = textsOf(sample).join("\n");
  assert.equal(sampleText.includes("<script>alert(1)</script>"), true);
  assert.equal(sampleText.includes("<img src=x onerror=alert(1)>"), true);
  assert.equal(sample.some((node) => node.attrs.href === "#/picks/p-20261011-01"), true);

  const hostile = {
    window: { since: null, until: null },
    picks: 1,
    findings: 3,
    summary: "0 lessons from 1 pick · 3 findings · 1 one-off",
    lessons: [],
    oneOffs: [{
      rank: null,
      key: "lesson:<img src=x onerror=alert(1)>",
      kind: "lesson",
      subject: "<img src=x onerror=alert(1)>",
      level: "review",
      stage: null,
      names: [],
      picks: ["../etc", "p-20261011-01"],
      pickCount: 1,
      count: 3,
      firstAt: "2026-10-11T00:00:00.000Z",
      lastAt: "2026-10-11T00:00:00.000Z",
      findings: [
        {
          key: "lesson:<img src=x onerror=alert(1)>",
          kind: "lesson",
          subject: "<img src=x onerror=alert(1)>",
          pickId: "../etc",
          seq: 4,
          ts: "2026-10-11T00:00:00.000Z",
          cand: null,
          label: null,
          pass: null,
          detail: "<script>alert(1)</script>",
        },
        {
          key: "lesson:<img src=x onerror=alert(1)>",
          kind: "lesson",
          subject: "<img src=x onerror=alert(1)>",
          pickId: "javascript:alert(1)",
          seq: 5,
          ts: "2026-10-11T00:00:00.000Z",
          cand: null,
          label: null,
          pass: null,
          detail: "<iframe src=javascript:alert(1)></iframe>",
        },
        {
          key: "lesson:<img src=x onerror=alert(1)>",
          kind: "lesson",
          subject: "<img src=x onerror=alert(1)>",
          pickId: "p-20261011-01",
          seq: 6,
          ts: "2026-10-11T00:00:00.000Z",
          cand: null,
          label: null,
          pass: null,
          detail: "<img src=x onerror=alert(1)>",
        },
      ],
      proposal: {
        level: "review",
        where: "<img src=x>",
        check: "check <script>no</script>",
        mustFailOn: [{ pickId: "../etc", seq: 4 }],
      },
    }],
    skipped: [{ pickId: "javascript:alert(1)", reason: "bad pick id" }],
  };
  const nodes = renderLessons(source, hostile);
  assertSafe(nodes, "hostile");
  const joined = textsOf(nodes).join("\n");
  assert.equal(joined.includes("../etc"), true);
  assert.equal(joined.includes("javascript:alert(1)"), true);
  assert.equal(joined.includes("<iframe src=javascript:alert(1)></iframe>"), true);
  assert.equal(nodes.some((node) => node.attrs.href === "#/picks/p-20261011-01"), true);
  assert.equal(nodes.some((node) => (node.attrs.href ?? "").includes("..")), false);
  assert.equal(nodes.some((node) => (node.attrs.href ?? "").includes("javascript")), false);
});

test("L19 500 picks", () => {
  const base = weekLogs();
  const logs: Log[] = [];
  for (let k = 0; k < 100; k += 1) {
    base.forEach((log, index) => {
      const pickId = dayId(k, index + 1);
      const events = clone(log.events ?? []);
      for (const event of events) {
        if (event.type === "pick_created") event.payload = { ...event.payload, id: pickId };
      }
      logs.push({ pickId, events });
    });
  }
  assert.equal(logs.length, 500);
  const started = performance.now();
  const report = reportOf(logs);
  const elapsed = performance.now() - started;
  assert.equal(report.summary, "13 lessons from 500 picks · 2700 findings · 0 one-offs");
  assert.equal(report.picks, 500);
  assert.equal(report.findings, 2700);
  assert.equal(report.lessons.length, 13);
  assert.equal(report.oneOffs.length, 0);
  assert.ok(elapsed < 1000, `elapsed ${elapsed.toFixed(1)} ms`);
});
